import{_ as t}from"./chunks/97922e77c3d19f61f9de.CPLfpGYK.js";import{_ as p,a as s}from"./chunks/920d83db104b71bb0c0d.aoSUT04O.js";import{_ as o,C as l,o as i,c as n,j as a,a as m,E as d,a5 as f}from"./chunks/framework.DNkHA0lr.js";const L=JSON.parse('{"title":"十年失败中汲取的人生教训","description":"","frontmatter":{"title":"十年失败中汲取的人生教训","originalTitle":"Life Lessons Learned From A Decade Of Failures","date":"2021-11-11","originalUrl":"https://thedankoe.com/letters/life-lessons-learned-from-a-decade-of-failures/","minutes":10,"sourceHash":"ae47fb106fe6dfb08d3e5688b13f08e8cb59f86429b1d7a9fa33654f263a11c0","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/life-lessons-learned-from-a-decade-of-failures/"}]]},"headers":[],"relativePath":"letters/life-lessons-learned-from-a-decade-of-failures.md","filePath":"letters/life-lessons-learned-from-a-decade-of-failures.md"}'),h={name:"letters/life-lessons-learned-from-a-decade-of-failures.md"};function c(u,e,_,g,b,k){const r=l("ArticleMeta");return i(),n("div",null,[e[0]||(e[0]=a("h1",{id:"十年失败中汲取的人生教训",tabindex:"-1"},[m("十年失败中汲取的人生教训 "),a("a",{class:"header-anchor",href:"#十年失败中汲取的人生教训","aria-label":'Permalink to "十年失败中汲取的人生教训"'},"​")],-1)),d(r),e[1]||(e[1]=f('<p>过去六个月里，我的生活一直是一连串模糊的突破、大想法和指数级进步。我一直在尝试改善我生活的方方面面——头脑、身体、精神、商业——在经历了十年生活的起起落落之后……一切都开始步入正轨。</p><p>当我刚开始举铁时，不到一年我就达到了“愚昧之巅”。</p><p><img src="'+t+'" alt=""></p><p>达克效应 (Dunning-Kruger Effect)</p><p>我痴迷于学习训练和营养的基础知识。我研究了莱恩·诺顿（Layne Norton）、艾伦·阿拉贡（Alan Aragon）、埃里克·赫尔姆斯（Eric Helms）等人，以及像马特·奥古斯（Matt Ogus）、克里斯·拉瓦多（Chris Lavado）、克里斯·琼斯（Chris Jones）、维特鲁威体格（Vitruvian Physique）、迈克尔·科里（Michael Kory）和罗布·利普塞特（Rob Lipsett）（<a href="https://open.spotify.com/episode/2LEFy0v4Hs18x5ZMT7BstX?si=f92bbfa7e3d44711&amp;utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">几个月前我有幸和他一起做了一期播客</a>）这样的元老级健身网红。</p><p>我成了一个 IIFYM（只要符合你的宏量营养素需求）狂热分子。对我来说唯一重要的是卡路里和宏量营养素。我把冷冻墨西哥卷饼、果酱馅饼以及任何我能弄到手的东西塞进嘴里，就为了凑够我的碳水、脂肪和蛋白质。</p><p>这在某种程度上奏效了。我长了不少肌肉，力量也大增。高四那年我卧推能做 275 磅的组——但我很快意识到，每天晚上狂喝胡椒博士（Dr. Pepper）一边打《光环3》（Halo 3）直到凌晨 3 点是行不通的。所以我开始进行实验。</p><h2 id="最优的-在此填入生活的某个方面-是一个神话" tabindex="-1">最优的（在此填入生活的某个方面）是一个神话 <a class="header-anchor" href="#最优的-在此填入生活的某个方面-是一个神话" aria-label="Permalink to &quot;最优的（在此填入生活的某个方面）是一个神话&quot;">​</a></h2><p>在过去的两年里，我尝试了纯素食、生酮、纯肉、低碳水、高碳水，以及“破产大学生”饮食法。</p><p>最近，我对伪纯肉饮食法变得教条起来。简而言之，你主要吃动物内脏、肌肉、动物胶质部位、应季水果、鸡蛋、乳制品和少量其他东西。非常强调要寻找你能找到的最高品质的食材。</p><p>我之所以如此教条，是因为我正在进行一场大戒断。我戒掉了酒精、社交活动，以及任何会妨碍我达到 185 磅目标的东西。我已经努力了 3 到 4 年想要达到那个体重，终于受够了自己毫无进展的状态。（<a href="https://open.spotify.com/episode/5Q8aAd1OKfKZT4mVhEVF85?si=833e193f4e0147a6&amp;utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">这期播客解释了我的 25 岁生日是如何引发这种心态剧变的</a>）。</p><p>既然我已经实现了那个目标，我感觉自己正在从“开悟之坡”走向“可持续平原”。</p><p>以下是我最近的感悟：</p><h2 id="在高强度的周期中找到平衡" tabindex="-1">在高强度的周期中找到平衡 <a class="header-anchor" href="#在高强度的周期中找到平衡" aria-label="Permalink to &quot;在高强度的周期中找到平衡&quot;">​</a></h2><p>奋斗逼文化喜欢美化“和尚模式”和高强度。当你有冲动为了一个次要目标而全力以赴时，我也喜欢那种经典的“和尚模式”——像激光一样专注的深度工作（deep work），一个月干完一年的活，因为灵感源源不断而失眠，乘着多巴胺和内在驱动力的浪潮前进——但是必须考虑到<em>可持续性</em>。</p><p>如果你在高强度或过度优化的状态下停留太久，你的生活质量就会达到一个收益递减的临界点。</p><p><img src="'+p+'" alt=""></p><p>当我开始过度优化时，<em>生活失去了它的滋味</em>。事情变得充满压力。日常惯例之外的任何事情都被视为一种负担。如果我不能控制我生活中的每一件小事，我就无法去享受它原本的样子。</p><p><strong>试图让你生活的每个方面都变得完美，会让你痛恨那些不完美。</strong> 当你这样做时，你就是在阻止自己享受人类天生自带的不完美。</p><p>自然是完美的。自然就是自然。人类被赋予了思想。但思想把事情搞得过于复杂，并误把自然解读为不完美。社会模仿自然——过度优化这一切并不是一种生活方式。</p><p>节假日回家看望家人，只会让我满脑子想着我能吃什么，我花了多少钱，以及我什么时候能回自己家“重新回到正轨”。我能想象到自己在评判他们那些“普通人”的行为。我无法享受和自己家人在一起的时光。今天晚些时候我回家时，我会刻意努力去享受和他们在一起的时光。</p><p>然而，这些高强度和优化的状态是必要的。如果没有它们，我就不会在脑海中巩固这些结论。所有的自我提升都源于觉知。觉知是通过潜入未知来发现的。<em>你无法改善你没有意识到的东西</em>——你无法意识到你不知道其存在的事物（它们存在于未知中……存在于不适中……存在于无限潜能的领域中）。</p><p>当你从这些高强度状态中走出来时——你在你指数级提升的任何方面都会从一个更高的基线开始运作。通过高强度，你会很快碰壁。<em>你在 1 个月内获得了 1 年的经验。</em> 当你撞上过度优化这堵隐喻的墙时，生活会给你上一课。你会从中吸取教训吗？</p><h2 id="基础-以及你对它们的坚持-才是最重要的" tabindex="-1">基础（以及你对它们的坚持）才是最重要的 <a class="header-anchor" href="#基础-以及你对它们的坚持-才是最重要的" aria-label="Permalink to &quot;基础（以及你对它们的坚持）才是最重要的&quot;">​</a></h2><p>通过我的高强度周期，我达到了一个更高的基线。我有了更好的饮食习惯，我新的基础盘也已经锁定。</p><p>基础是当事情变得过于激烈（或过于松懈）时你可以依靠的东西。它们是你获得结果的系统。它们是你取得进步的“杠杆（levers）”。</p><p>在你追求个人和商业发展的过程中，当你感到迷茫、不知所措或失去方向时，回到基础——把它们写下来。</p><p><strong>我现在的健康基础是：</strong></p><ul><li>每天吃生肝、骨汤和肌肉肉，进行一种伪“从头吃到尾”的纯肉饮食。在重要营养素方面覆盖了大部分基础需求。</li><li>水果、白米和块茎类来补充碳水化合物。</li><li>发酵食品，如羊奶开菲尔。</li><li>我的“开悟灵丹妙药”过去是、将来也会是我的主食。</li><li>每周 3 次全身训练</li><li>每周 4 次跑步和冲刺跑</li><li>周末进行轻度活动（比如徒步）</li><li>每磅体重摄入 1 克蛋白质</li><li>压力和情绪调节</li></ul><p>既然我现在正向更多社交活动敞开心扉，我又退回到了上面提到的二八定律。如果我能在 80% 的时间里坚持这个原则，可以肯定地说，我将在健康方面继续取得指数级的进步。目前我还是滴酒不沾，它惹了太多的麻烦。不过，我正开心地尝试微量摄入裸盖菇素（零卡路里，而且对写作有极大的好处）。</p><p>让我深有感触的是那些把可持续性记在心里的“灵活节食者”群体。再进一步，比如 Instagram 上的 Timbahwolf，他吃得像屎一样，体格却比 99% 的社交网红都要好。</p><p>巨石强森（The Rock）吃煎饼。迈克尔·菲尔普斯（Michael Phelps）抽大麻，吃成吨的披萨。我们在推特上看到的，是我们主动去接触的东西。我完全忘记了我当初是怎么走过来的，并且可能错误地归因了我的进步。</p><p><strong>我的反思是：</strong> 对<em>我</em>的头脑清晰度、皮肤和能量水平影响最大的，是不暴饮暴食、保持精瘦、有目标感、调节压力、训练和运动。不一定是很多人推崇的那种超高品质高脂饮食。<em>大多数人停止了暴饮暴食，开始运动，保持一致性，并锁定了其他一些原则</em>——然后他们接着说，这得归功于诸如吃生肝或生酮等某种魔法。似乎健康行业里人们谈论的因果关系被搞错了——或者被极端化以推销某种产品。</p><p>我说这些不是为了动摇你的观点。我说这些是为了让你能以批判性的眼光对待生活。带着开放的心态。不要因为你限制了对某个特定领域<em>所有方面</em>的认知和了解，就去限制那些能带来快乐的事情。我重视批判性思维和细微差别——我将更多地朝这个方向发展，而不是对某种特定的饮食方式如此教条。</p><p>我打算开始狂吃垃圾食品吗？不。我会像你该做的那样去测试和实验。有了这个新的基线和认知水平，我将能够准确地看清它对我身体的短期影响。</p><p>旅行的时候，你敢打赌我绝对不会错过意面、面包和其他碳水来源这类通常被妖魔化的食物。我下周在德州大吃特吃烤肉时，说不定还会在 <a href="https://instagram.com/thedankoe?utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">Insta</a> 上发点照片。这些食物被一些研究人员妖魔化，又被另一些人捧上天。</p><p>如果你想打破你所信奉的任何健康意识形态或宗教信仰，<a href="https://open.spotify.com/episode/1G5UGm5BqnbAFoefA20zx1?si=Yjrk8KDZThqDY-y8yKWWhg&amp;utm_campaign=The%20Mastery%20Letter&amp;utm_medium=email&amp;utm_source=Revue%20newsletter" target="_blank" rel="noreferrer">我已经开始听乔·罗根（Joe Rogan）早前与莱恩·诺顿和多姆·达戈斯蒂诺（Dom D’Agostino）做的一期播客</a>（他们在辩论灵活节食法与生酮饮食）。</p><p>这就是这些“高强度周期”的美妙之处。我的健康哲学是我在改善它的十年中积累的经验的融合。它得到了来自各方的研究和经验的支持。这是很强大的，对于我生活中的其他支柱来说也是如此。</p><p>这并没有消除自律生活方式的价值。这就是一种自律的生活方式。这种“平衡”的生活方式比完全戒绝某些东西更难做到——但潜在的回报也更高。这就是为什么需要高强度来寻找平衡。我多年来一直在原地打转，因为我不敢全力以赴。我害怕去学习生活在未知中为我准备的教训。</p><p>这与我以前的饮食习惯截然不同——却又非常相似。我是通过有意识的实验才达到这一步的。</p><h2 id="生活就是一系列科学实验" tabindex="-1"><strong>生活就是一系列科学实验</strong> <a class="header-anchor" href="#生活就是一系列科学实验" aria-label="Permalink to &quot;**生活就是一系列科学实验**&quot;">​</a></h2><p>我在这里一直是在用健康来举例……但这适用于生活的各个领域。</p><p><em>每一个话题都可以被争论和研究到天荒地老。</em> 如果我想在整体健康问题上变得教条，我能找到支持这种做法的研究和令人信服的论据。但这并没有什么乐趣。乐趣来自于保持开放的心态，把事物保留在可能性的领域里，质疑一切，并通过直接经验巩固一种带有细微差别的视角。</p><p>生活就是实验。了解你喜欢什么和不喜欢什么。看看什么有效，什么无效。慢慢地对你这个角色所拥有的特质、技能和智慧进行小规模的升级。这些经验和升级上的小小提升会在人生的游戏中带来巨大的成果（有时候你甚至注意不到它们，直到你回过头来反思你的进步）。</p><p>就我而言，我在大学里换了 6 次专业，直到接触到编程。那引发了一场由多巴胺驱动的疯狂学习编程之旅。那促使我去尝试自由职业和其他在线商业模式。那又促使我创办了 Modern Mastery。这种进步是巨大的。</p><p>如果你不知道该追求什么——你的毕生事业、你的目标、你的热情——<strong>你必须开始做实验</strong>。你需要把屎扔到墙上，看看什么能粘得住。<em>你需要尝试足够多的东西，直到你体验到那种将你拉入高强度状态的内在驱动力。</em> 这要归功于多巴胺。多巴胺将信号与噪音分离开来。多巴胺告诉你，你做的事情是对的（当心：廉价多巴胺）。</p><p>你怎么开始做实验？你要把你生活的所有领域都当作一个科学项目。</p><p><img src="'+s+'" alt=""></p><p>科学方法</p><p>你的身体是一个项目。你的健康是一个项目。你的人际关系是一个项目。你的事业是一个项目。所有这些之中还嵌套着更多的项目。“项目心态”非常强大。我的室友已经开始把他的身体当成一个项目。这个简单的举动让他开始追踪自己的进步，减掉了80磅，并且开始留心他是如何在这个项目上“下功夫”的。</p><p>项目意味着期望的结果（改进）、完成的步骤（目标和指标），以及让你更接近完成的行动（优先级）。</p><p>实验意味着你需要考虑到风险、意图、测试和迭代。这意味着你必须把实验坚持到底。你不能在事情开始好转之前就放弃。</p><p>它们也意味着失败。并非所有的实验都是成功的。当你把它当作一个项目时，你就更容易摆脱对结果的执念。你把失败看作是迭代和改进的机会。失败是关于如何改进的反馈。绕回到觉察力上——<em>你无法改进你没有意识到的东西。</em></p><p>你需要带着开放和好奇的心态进入你的实验。这将为提出问题留出空间。好奇心是由问题驱动的。问题：如果我尝试这件我以前从未尝试过的事情，生活会是什么样？</p><p>你会自然而然地感觉到潜入未知的吸引力。如果没有，那就继续问问题，直到你感到充满活力。那就是对你冒险的召唤。召唤你成为未知的探索者。召唤你开始实现你的潜力。</p><h2 id="生命的意义在于传承你的经验" tabindex="-1"><strong>生命的意义在于传承你的经验</strong> <a class="header-anchor" href="#生命的意义在于传承你的经验" aria-label="Permalink to &quot;**生命的意义在于传承你的经验**&quot;">​</a></h2><p>实验 = 经验。</p><p>实验是你找到适合自己方法的方式。实验是你形成个人健康、财富和人际关系哲学的方式——这让你能够传承你的教训，并在此过程中赚钱（根据古今导师的说法，这可以说是生命的意义，即自我超越）。</p><p>实验是你形成人生哲学的方式。一本让你保持在令人愉悦、可持续和充满成就感的道路上的操作手册。</p><p>既然我们在这里经常谈论商业——这就完美地联系在了一起。商业——在我们的情况下是线上业务——是你追求毕生事业的载体。你的毕生事业包括追求你的兴趣（实验），成为唯一的细分领域（懂得如何营销、销售和分发），并以终端用户能够消化和执行的方式打包你的经验。金钱只是你不可替代价值的副产品。</p><p>如果你喜欢这篇博文——你可以通过订阅 <a href="https://join.modernmastery.co/the-mastery-letter" target="_blank" rel="noreferrer">The Mastery Letter</a> 来获得所有文章的抢先阅读权。</p><hr><p><a href="/en/letters/life-lessons-learned-from-a-decade-of-failures">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',63))])}const M=o(h,[["render",c]]);export{L as __pageData,M as default};
